using System;
namespace LWS.TruckDodgeball {public static class DodgeFixtures {
 public static int Run(){int count=0;void Check(bool condition,string message){count++;if(!condition)throw new InvalidOperationException("Dodge rule fixture: "+message);}var rules=new DodgeRules();rules.Reset(4,4);Check(rules.Count==8&&rules.Remaining(0)==4&&rules.Remaining(1)==4,"eight distinct alive trucks");for(int i=0;i<8;i++)Check(rules.Team(i)==(i<4?0:1),"team ownership "+i);Check(!rules.FinishStep(),"live teams do not finish early");Check(rules.Eliminate(0)&&!rules.Eliminate(0),"eliminate once only");for(int i=1;i<8;i++)rules.Eliminate(i);Check(rules.FinishStep()&&rules.RoundWinner==-1&&rules.wins[0]==0&&rules.wins[1]==0,"all final falls batch into draw");Check(!rules.FinishStep()&&!rules.Eliminate(1),"result locks");rules.NextRound();Check(rules.Remaining(0)==4&&rules.Remaining(1)==4,"draw round resets all bodies");for(int round=0;round<3;round++){for(int i=4;i<8;i++)rules.Eliminate(i);Check(rules.FinishStep()&&rules.RoundWinner==0&&rules.wins[0]==round+1,"team heat result");Check(!rules.FinishStep()&&rules.wins[0]==round+1,"no duplicate round point");if(round<2)rules.NextRound();}Check(rules.Winner==0,"first to three");rules.Reset(1,2);Check(rules.Winner==-1&&rules.wins[0]==0&&rules.wins[1]==0&&rules.Count==3,"rematch clears authoritative state");rules.Draw();Check(rules.Locked&&rules.RoundWinner==-1&&rules.wins[0]==0,"bounded timer draws without awarded point");Check(DodgeRules.HitEliminates(0,1,false,false),"enemy live ball eliminates");Check(!DodgeRules.HitEliminates(-1,0,false,false),"neutral ball safe");Check(!DodgeRules.HitEliminates(0,0,false,false),"friendly ball safe");Check(!DodgeRules.HitEliminates(1,0,true,false),"striker grace safe");Check(!DodgeRules.HitEliminates(1,0,false,true),"timed return safe");Check(DodgeRules.PreferStrike(1,9,2,2,1,0),"earlier valid strike intent precedes later input");Check(!DodgeRules.PreferStrike(2,1,0,1,9,2),"later input cannot replace earlier intent by callback order");Check(DodgeRules.PreferStrike(1,1,2,1,4,0),"equal input time chooses actual closer truck");Check(!DodgeRules.PreferStrike(1,4,0,1,1,2),"farther contender cannot win by slot iteration");Check(DodgeRules.PreferStrike(1,1,0,1,1,1)&&!DodgeRules.PreferStrike(1,1,1,1,1,0),"exact tie uses explicit rotating rank");Check((0+1)%2>(1+1)%2&&(0+2)%2<(1+2)%2,"neutral simultaneous tie rotates between teams across rounds");return count;}
}}
